  /**
   * Content-addressed artifact id (`job_result` only).
   */
  artifact_id: string | null;
  /**
   * Sha256 hex digest of the artifact bytes (`job_result` only).
   */
  sha256: string | null;
  /**
   * Artifact byte length (`job_result` only).
   */
  size_bytes: bigint | null;
